var done = new Stack<string>();
var log = new List<string>();
var steps = new (string Name, bool Ok)[]
{
    ("Order", true), ("Payment", true),
    ("Inventory", false), ("Shipping", true)
};
foreach (var s in steps)
{
    if (!s.Ok)
    {
        log.Add("fail " + s.Name);
        while (done.Count > 0)
            log.Add("undo " + done.Pop());
        break;
    }
    done.Push(s.Name);
    log.Add("do " + s.Name);
}
Console.WriteLine(string.Join("\n", log));
